action.command:
node -e "
const fs = require('fs');
const path = require('path');
let input = '';
process.stdin.on('data', d => input += d);
process.stdin.on('end', () => {
  try {
    const ctx = JSON.parse(input);
    const taskDesc = (ctx.task && ctx.task.description) || (ctx.taskDescription) || '(task description unavailable)';
    const taskId   = (ctx.task && ctx.task.id)          || (ctx.taskId)          || '';
    const summary  = (ctx.summary)                                                || '(no summary provided)';
    const decisions = (ctx.decisions)                                             || '(none recorded)';
    const modified  = (ctx.modifiedFiles && ctx.modifiedFiles.length)
                       ? ctx.modifiedFiles.join(', ')
                       : '(none)';
    const ts = new Date().toISOString();
    const logPath = path.join(process.env.WORKSPACE_ROOT || '.', 'docs', 'ai-collaboration-log.md');
    const entry = [
      '## ' + ts,
      '**Event:** Task Completed' + (taskId ? ' — Task #' + taskId : ''),
      '',
      '**Task:** ' + taskDesc,
      '',
      '**Summary of Actions:**',
      '> ' + summary,
      '',
      '**Decisions Made:**',
      '> ' + decisions,
      '',
      '**Files Modified:** ' + modified,
      '',
      '---',
      ''
    ].join('\n');
    fs.mkdirSync(path.dirname(logPath), { recursive: true });
    fs.appendFileSync(logPath, entry, 'utf8');
  } catch (e) {
    // non-blocking — never interrupt the session
  }
});
"
